import{_ as o,o as t,c as a,an as i}from"./chunks/framework.BIN2LiFE.js";const h=JSON.parse('{"title":"Patterns to Avoid","description":"","frontmatter":{},"headers":[],"relativePath":"perf/patterns_to_avoid.md","filePath":"perf/patterns_to_avoid.md","lastUpdated":null}'),r={name:"perf/patterns_to_avoid.md"};function n(d,e,l,c,s,p){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="Patterns-to-Avoid" tabindex="-1">Patterns to Avoid <a class="header-anchor" href="#Patterns-to-Avoid" aria-label="Permalink to &quot;Patterns to Avoid {#Patterns-to-Avoid}&quot;">​</a></h1><h2 id="Scalar-indexing" tabindex="-1">Scalar indexing <a class="header-anchor" href="#Scalar-indexing" aria-label="Permalink to &quot;Scalar indexing {#Scalar-indexing}&quot;">​</a></h2><p>Accessing elements of an NDArray one at a time (e.g., <code>arr[5]</code>) is slow and should be avoided. Indexing like this requires data to be transferred between device and host and maybe even communicated across nodes. Scalar indexing will emit an error which can be opted out of with <code>@allowscalar</code> or <code>allowscalar() do ... end</code>. Several functions in the existing API invoke scalar indexing and are intended for testing (e.g., the <code>==</code> operator).</p><h2 id="Implicit-promotion" tabindex="-1">Implicit promotion <a class="header-anchor" href="#Implicit-promotion" aria-label="Permalink to &quot;Implicit promotion {#Implicit-promotion}&quot;">​</a></h2><p>Mixing integral types of different size (e.g., <code>Float64</code> and <code>Float32</code>) will result in implicit promotion of the smaller type to the larger types. This creates a copy of the data and hurts performance. Implicit promotion from a smaller integral type to a larger integral type will emit an error which can be opted out of with <code>@allowpromotion</code> or <code>allowpromotion() do ... end</code>. This error is common when mixing literals with <code>NDArrays</code>. By default a floating point literal (i.e., 1.0) is <code>Float64</code> but the default type of an <code>NDArray</code> is <code>Float32</code>.</p>',5)])])}const f=o(r,[["render",n]]);export{h as __pageData,f as default};
